// Üretilen dosya: tool/ozgun/uret.py. Araştırma Yöntemleri · Veriyi yorumlama, nedensellik-korelasyon, yanlılık ve geçerlilik (zor).
const ozResearch4Zor = <(String, String, List<String>, String)>[
  ('Pearson korelasyon katsayısının sıfıra çok yakın çıkması aşağıdakilerden hangisini kesin olarak göstermez?', 'Değişkenler arasında hiçbir ilişki olmadığını', ['Güçlü bir doğrusal ilişki bulunmadığını', 'Doğrusal bir eğilimin zayıf olduğunu', 'Noktaların düz bir çizgi etrafında toplanmadığını'], 'Pearson r yalnızca doğrusal ilişkiyi ölçer. U biçimli gibi doğrusal olmayan güçlü bir ilişki varken bile r sıfıra yakın çıkabilir.'),
  ('Bir egzersiz çalışmasında kaygı düzeyi ile performans arasında ters U biçimli bir ilişki var: orta kaygıda performans en yüksek, çok düşük ve çok yüksek kaygıda düşük. Pearson r için en olası sonuç nedir?', 'Sıfıra yakın bir değer', ['+1\'e yakın bir değer', '-1\'e yakın bir değer', 'Tanımsız bir değer'], 'Ters U biçiminde eğrinin yükselen ve alçalan kolları birbirini dengeler, bu yüzden doğrusal katsayı sıfıra yakın çıkar. Yine de değişkenler arasında güçlü bir ilişki vardır.'),
  ('Bir değişkenin karıştırıcı sayılabilmesi için aşağıdaki koşullardan hangisi gereklidir?', 'Hem incelenen nedenle hem de sonuçla ilişkili olması', ['Yalnızca sonuçla ilişkili olması', 'Araştırmacı tarafından bilinçli olarak değiştirilmesi', 'Nedenin bir sonucu olarak ortaya çıkması'], 'Karıştırıcı, maruziyet ve sonuçla birlikte ilişkilidir ve nedensel yolun üzerinde değildir. Nedenin sonucu olan değişken aracı değişkendir.'),
  ('Bir maruziyet ile hastalık arasındaki göreli riskin 1,1 yerine 20 bulunması nedensellik açısından neden daha ikna edicidir?', 'Çok güçlü bir ilişkiyi gizli bir karıştırıcıyla açıklamak zordur.', ['Göreli risk 20 olduğunda hiçbir karıştırıcı değişken var olamaz.', 'Zayıf ilişkiler hiçbir zaman nedensel değildir.', 'Göreli risk büyüdükçe örneklem otomatik olarak büyür.'], 'İlişkinin gücü Bradford Hill ölçütlerindendir. Çok büyük bir etkiyi açıklayacak bir karıştırıcının da çok güçlü olması gerekir; yine de zayıf ilişkiler de nedensel olabilir.'),
  ('Rastgele atama ile rastgele örnekleme arasındaki fark en doğru biçimde hangisinde verilmiştir?', 'Atama iç geçerliliği, örnekleme genellenebilirliği destekler.', ['İkisi de yalnızca dış geçerliliği destekler.', 'Atama genellenebilirliği, örnekleme nedensel çıkarımı destekler.', 'İkisi aynı işlemin farklı adlarıdır.'], 'Rastgele atama gruplar arası karşılaştırmayı adil kılarak nedensel çıkarımı (iç geçerlilik) güçlendirir. Rastgele örnekleme ise sonuçların evrene genellenmesine yardım eder.'),
  ('Bir ilacın etkisini araştıran çalışmada katılımcılar rastgele atanmış, ancak ilaç grubundakilerin %40\'ı ilacı almayı bırakmıştır. Sonuçlar başlangıçtaki atamaya göre analiz edilirse buna ne ad verilir?', 'Tedavi niyeti analizi', ['Protokole uygun (yalnız uyumlu hastalar) analizi', 'Alt grup analizi', 'Ekolojik analiz'], 'Tedavi niyeti analizi herkesi atandığı grupta değerlendirir ve rastgele atamanın sağladığı dengeyi korur. Yalnız uyum gösterenleri almak yeniden seçim yanlılığı doğurabilir.'),
  ('Bir bursun yalnızca sınavda 70 ve üzeri alanlara verildiği bir sistemde, 69 ile 71 alan öğrencilerin sonraki başarısını karşılaştırmanın mantığı nedir?', 'Eşiğin iki yanındakiler benzer olduğu için farkın bursa bağlanabilmesi', ['69 alanların daha zeki olduğunun bilinmesi', 'Eşiğin uzağındaki öğrencilerin çok daha fazla ve güvenilir veri sağlaması', 'Burs alanların hep başarısız olması'], 'Bu yaklaşım "regresyon süreksizlik" düzeni olarak bilinir. Eşiğe çok yakın kişiler neredeyse rastgele biçimde iki tarafa düşer.'),
  ('Bir yasa yalnızca A ilinde uygulanmaya başlanıyor. Araştırmacı, yasadan önceki ve sonraki değişimi A ile benzer eğilimdeki B ili arasında karşılaştırıyor. Bu yöntemin dayandığı temel varsayım nedir?', 'Yasa olmasaydı iki ilin eğilimlerinin paralel süreceği', ['İki ilin nüfusunun ve gelir düzeyinin tam olarak eşit olduğu', 'B ilinin yasadan önce hiç değişmediği', 'Yasanın B ilinde de uygulandığı'], 'Farkların farkı yöntemi, karşılaştırma grubunun eğiliminin uygulama grubunun "yasa olmasaydı" izleyeceği yolu temsil ettiğini varsayar.'),
  ('A hastanesinde ameliyatların %90\'ı, B hastanesinde %85\'i başarılı. Ancak hem hafif hem de ağır vakalarda B\'nin başarı oranı daha yüksek. Bu tablonun en olası açıklaması nedir?', 'B hastanesinin çok daha fazla ağır vaka üstlenmesi', ['A hastanesinin başarı oranlarını yanlış hesaplaması', 'Hafif vakaların hiç ameliyat edilmemesi', 'İki hastanenin aynı hastaları tedavi etmesi'], 'Ağır vakaların başarı oranı doğal olarak düşüktür. B bu vakalardan çok aldığında genel oranı düşer; vaka ağırlığına göre bakıldığında ise daha başarılıdır.'),
  ('Bir tedavi için böbrek taşı verisinde, küçük taşlarda A tedavisi 81/87, B tedavisi 234/270; büyük taşlarda A 192/263, B 55/80 başarı sağlamıştır. Toplamda hangi tedavi daha yüksek ham başarı oranına sahiptir?', 'B', ['A', 'İkisi tam olarak eşit', 'Verilerle belirlenemez'], 'Toplamda A: 273/350 = %78, B: 289/350 = %83\'tür. Oysa her iki taş boyunda da A daha başarılıdır; bu, Simpson paradoksunun bilinen bir örneğidir.'),
  ('Simpson paradoksu riski taşıyan bir veri setinde, birleştirilmiş tablo mu yoksa alt grup tabloları mı esas alınmalıdır sorusuna en doğru yaklaşım hangisidir?', 'Karar, değişkenler arasındaki nedensel yapıya bağlıdır.', ['Her zaman birleştirilmiş tablo esas alınır.', 'Her zaman en küçük alt grup esas alınır.', 'Hangi tablo daha yüksek oran veriyorsa o seçilir.'], 'Gruplama değişkeni bir karıştırıcıysa alt gruplara, uygulamanın bir sonucuysa çoğu kez birleşik veriye bakmak gerekir. Karar istatistikle değil, nedensel akıl yürütmeyle verilir.'),
  ('1930\'larda ABD eyaletlerinde göçmen oranı yüksek olan eyaletlerde okuryazarlığın da daha yüksek olduğu bulunmuş; ancak bireysel düzeyde göçmenlerin okuryazarlık oranı daha düşüktü. Bu çelişkinin açıklaması nedir?', 'Göçmenlerin okuryazarlığı yüksek eyaletlere yerleşmesi', ['Okuryazarlık ölçümlerinin eyaletten eyalete hiç değişmeden uygulanması', 'Göçmenlerin hiç sayılmamış olması', 'Bireysel verinin her zaman hatalı olması'], 'William Robinson\'ın 1950 tarihli çalışmasındaki bu örnekte grup düzeyi ilişki, yerleşim tercihinden kaynaklanıyordu. Eyalet verisi bireysel ilişkiyi tersine göstermişti.'),
  ('Bireysel verilerden elde edilen bir sonucu doğrudan gruplara ya da toplumlara aktarmanın tersine yapılan hata hangi adla bilinir?', 'Atomistik yanılgı', ['Ekolojik yanılgı', 'Simpson paradoksu', 'Kiraz toplama'], 'Ekolojik yanılgının tersi olan atomistik yanılgı, bireyler arasındaki ilişkilerin grup düzeyinde de aynı biçimde geçerli olacağını varsaymaktır.'),
  ('Bir pilot eğitmeni, kötü inişten sonra azarladığı öğrencilerin bir sonraki inişte daha iyi yaptığını, iyi inişten sonra övdüklerinin ise kötüleştiğini fark ediyor ve "övgü zararlı, azar faydalı" sonucuna varıyor. Bu yorumun hatası nedir?', 'Değişim, tepkiden bağımsız olarak ortalamaya dönüşle açıklanabilir.', ['Azarlamanın her koşulda öğrenme performansını düşürdüğü kesin olarak kanıtlanmıştır.', 'İniş performansı ölçülebilir bir değişken değildir.', 'Övgü ve azar aynı öğrenciye verilmiştir.'], 'Daniel Kahneman\'ın aktardığı bu örnekte, olağandışı iyi ya da kötü inişleri doğal olarak daha olağan inişler izler. Eğitmen bunu kendi tepkisinin etkisi sanmıştır.'),
  ('Bir hastanenin acil servisine başvuranlar üzerinde yapılan çalışmada iki hastalığın birbiriyle ilişkili göründüğü, ancak toplumda böyle bir ilişki bulunmadığı anlaşılmıştır. Bu yanlılık türü hangi adla bilinir?', 'Berkson yanlılığı', ['Hawthorne yanlılığı', 'Yayın yanlılığı', 'Sağlıklı işçi etkisi'], 'İki hastalıktan herhangi biri hastaneye yatma olasılığını artırıyorsa, hastane örnekleminde ikisi arasında yapay bir ilişki ortaya çıkabilir. Bu, 1946\'da Joseph Berkson\'ın tanımladığı seçim yanlılığıdır.'),
  ('Bir meta-analizde küçük çalışmaların büyük etkiler, büyük çalışmaların ise küçük etkiler bildirdiği görülüyor. Huni grafiğinde de küçük ve etkisiz çalışmaların bulunduğu bölge boş. Bu bulgu en çok neye işaret eder?', 'Küçük ve sonuçsuz çalışmaların yayımlanmadığına', ['Büyük çalışmaların daha dikkatsiz yürütüldüğüne', 'Etkinin örneklem büyüdükçe gerçekten ve doğal olarak azaldığına', 'Meta-analizin hiçbir yanlılık taşımadığına'], 'Huni grafiğindeki asimetri, küçük örneklemli ve olumsuz sonuçlu çalışmaların eksik olduğunu düşündürür; bu yayın yanlılığının işaretidir.'),
  ('Hawthorne etkisi ile ilgili hangi değerlendirme daha doğrudur?', 'Yeniden incelemeler etkinin büyüklüğünü tartışmalı kılmıştır.', ['Etki her araştırmada aynı büyüklükte ve sürekli olarak, istisnasız görülür.', 'Yalnızca hayvan deneylerinde ortaya çıkar.', 'Etki, katılımcılar gözlendiklerini bilmediğinde daha güçlüdür.'], 'Sonraki analizler, Hawthorne verilerinin farklı yorumlanabildiğini ve etkinin sanıldığı kadar güçlü olmayabileceğini öne sürmüştür. Yine de gözlenmenin davranışı değiştirebileceği ilkesi önemlidir.'),
  ('Sosyal beğenirlik yanlılığı neden yalnızca "yanıt güvenirliği" değil, aynı zamanda "geçerlilik" sorunudur?', 'Ölçüm, kişinin kendini sunma eğilimini de ölçer.', ['Yanıtların her tekrarda rastgele değişmesine yol açar.', 'Örneklem büyüklüğünü doğrudan azaltır.', 'İstatistiksel testlerin hesaplanmasını imkânsız kılar.'], 'Yanlılık sistematik olduğundan aynı kişi her seferinde benzer biçimde abartabilir; ölçüm tutarlı olsa da amaçlanan yapıyı doğru yansıtmaz.'),
  ('Kontrol grubuna düşen öğretmenlerin, deney grubunun gerisinde kalmamak için olağandan çok çalışması hangi adla bilinir?', 'John Henry etkisi', ['Pygmalion (öğretmen beklentisi) etkisi', 'Plasebo etkisi', 'Bumerang etkisi'], 'Kontrol grubunun rekabet duygusuyla performansını artırması, müdahalenin etkisini maskeleyebilir. Ad, makineyle yarışan efsanevi demiryolu işçisinden gelir.'),
  ('Psikoloji araştırmalarında katılımcıların büyük çoğunluğunun Batılı, eğitimli, sanayileşmiş, zengin ve demokratik toplumlardan gelmesi eleştirisi hangi kısaltmayla anılır?', 'WEIRD', ['PICO', 'SMART', 'FINER'], 'Joseph Henrich ve arkadaşlarının 2010 tarihli makalesiyle yaygınlaşan bu eleştiri, bulguların insanlığın genelini temsil etmeyebileceğini vurgular.'),
  ('Bir okuma anlama testinde metinler çok uzun ve kelimeler çok ağır olduğu için puanlar daha çok kelime bilgisini ve okuma hızını yansıtıyor. Bu durum hangi geçerlilik tehdidine örnektir?', 'Yapıyla ilgisiz varyans', ['Ortalamaya dönüş', 'Seçim yanlılığı', 'Hayatta kalan yanlılığı'], 'Puanları amaçlanan yapı dışındaki etkenler (hız, kelime bilgisi) belirliyorsa ölçüm yapıyla ilgisiz varyans taşır ve yapı geçerliliği zayıflar.'),
  ('Hedef tahtası benzetmesinde, atışlar tahtanın her yerine dağılmış ama ortalamaları tam merkezde ise bu durum neyi temsil eder?', 'Düşük güvenirlik, sistematik sapmanın olmaması', ['Yüksek güvenirlik, yüksek geçerlilik', 'Yüksek güvenirlik, düşük geçerlilik', 'Düşük güvenirlik ve merkezden uzak sistematik sapma'], 'Dağınık atışlar tutarsızlığı (rastlantısal hata), merkezdeki ortalama ise sistematik bir kayma olmadığını gösterir. Tek tek ölçümler yine de güvenilmezdir.'),
  ('Bir ölçme aracının güvenirliği çok düşükse, bu aracın başka bir değişkenle gösterebileceği korelasyon için ne beklenir?', 'Gözlenen korelasyon gerçek ilişkiden düşük çıkar.', ['Gözlenen korelasyon her zaman tam 1 olur.', 'Gözlenen korelasyon gerçek ilişkiden yüksek çıkar.', 'Güvenirlik korelasyonu hiçbir biçimde etkilemez.'], 'Rastlantısal ölçme hatası ilişkiyi zayıflatır; buna "zayıflama" (attenuation) denir. Güvenilmez ölçümlerle gerçek ilişkiler olduğundan küçük görünür.'),
  ('Ruh hâli gibi kısa sürede doğal olarak değişen bir özelliği ölçen bir ölçek için test-tekrar test güvenirliğinin düşük çıkması nasıl yorumlanmalıdır?', 'Özellik değiştiği için düşüklük ölçeğin kusuru sayılmayabilir.', ['Ölçek kesin olarak geçersizdir ve hiçbir araştırmada kullanılmamalıdır.', 'Ölçeğin iç tutarlılığı da mutlaka düşüktür.', 'Puanlayıcılar arası uyum sıfırdır.'], 'Test-tekrar test güvenirliği kararlı özellikler için anlamlıdır. Durumsal özelliklerde puan değişimi gerçek değişimi yansıtabilir; iç tutarlılık daha uygun bir göstergedir.'),
  ('Cronbach alfa değerinin çok yüksek (örneğin 0,98) çıkması neden her zaman iyi bir işaret değildir?', 'Maddelerin neredeyse aynı şeyi tekrar ettiğini gösterebilir.', ['Alfanın 0,70\'i aşması ölçeği geçersiz kılar.', 'Yüksek alfa, maddelerin birbirinden bağımsız olduğunu gösterir.', 'Alfa yalnızca iki maddeli ölçeklerde hesaplanır.'], 'Aşırı yüksek alfa gereksiz tekrar ve dar bir kapsam anlamına gelebilir. Ayrıca alfa, madde sayısı arttıkça da yükselir.'),
  ('Bir öğrencinin sınavda aldığı 72 puan için ölçmenin standart hatası 4 puan olarak verilmiştir. Bu bilgi en doğru biçimde nasıl yorumlanır?', 'Gerçek puan büyük olasılıkla 72\'nin birkaç puan çevresindedir.', ['Öğrencinin gerçek puanı kesin olarak 72\'dir.', 'Öğrencinin gerçek puanı kesin olarak 76\'dır.', 'Sınavdaki her soru 4 puan değerindedir ve öğrenci 18 soruyu doğru yapmıştır.'], 'Ölçmenin standart hatası, gözlenen puanın gerçek puan çevresinde ne kadar dalgalanabileceğini gösterir. Yaklaşık %68 olasılıkla gerçek puan 68–76 aralığındadır.'),
  ('Bir çalışmada iki grup ortalaması için ayrı ayrı %95 güven aralıkları biraz örtüşüyor. Bundan "fark kesinlikle anlamsızdır" sonucunu çıkarmak neden hatalı olabilir?', 'Hafif örtüşmede bile farkın kendi aralığı sıfırı içermeyebilir.', ['Örtüşen aralıklar her zaman anlamlı bir farkı kanıtlar.', 'Güven aralıkları ortalamalar için hesaplanamaz.', 'Aralıkların örtüşmesi örneklemin çok küçük olduğunu kesin gösterir.'], 'İki ayrı aralığın biraz örtüşmesi, fark için hesaplanan aralığın sıfırı içerdiği anlamına gelmez. Doğru karşılaştırma farkın güven aralığıyla yapılır.'),
  ('Bir araştırmacı, gücü yalnızca 0,30 olan küçük bir çalışmada anlamlı bir sonuç buluyor. Bu sonucun güvenilirliği konusunda hangi uyarı yerindedir?', 'Düşük güçte anlamlı bulgular etkiyi abartma eğilimindedir.', ['Düşük güç, anlamlı bulguların her zaman doğru olduğunu gösterir.', 'Güç düşükse Tip I hata olasılığı sıfır olur.', 'Güç yalnızca anlamsız sonuçlarda önemlidir.'], 'Küçük çalışmalar ancak şans eseri büyük çıkan etkileri yakalayabilir. Bu nedenle düşük güçte anlamlı çıkan etkiler çoğu zaman gerçeğinden büyüktür ("kazananın laneti").'),
  ('Etkisi olmayan bir besin takviyesi için birbirinden bağımsız 20 farklı sağlık sonucu test edilirse ve her biri 0,05 düzeyinde değerlendirilirse, en az birinin şans eseri anlamlı çıkma olasılığı yaklaşık ne kadardır?', '%64', ['%5', '%20', '%95'], 'En az bir yanlış pozitif olasılığı 1 − 0,95²⁰ ≈ 0,64\'tür. Çok sayıda test yapıldığında şans eseri "bulgu" neredeyse kaçınılmaz hâle gelir.'),
  ('Bir araştırmacı her 10 katılımcıda bir analiz yapıyor ve p < 0,05 bulduğu anda veri toplamayı durduruyor. Bu uygulamanın sonucu nedir?', 'Yanlış pozitif olasılığı %5\'in belirgin biçimde üstüne çıkar.', ['Yanlış pozitif olasılığı %5\'in altına iner.', 'Sonuçlar daha az yanlı olur, çünkü daha az katılımcı kullanılır.', 'Çalışmanın gücü değişmeden kalır ve hata oranı etkilenmez.'], 'Tekrarlanan ara bakışlar her biri ayrı bir şans vermek gibidir. Önceden planlanmış ve düzeltilmiş ara analizler yapılmazsa hata oranı şişer.'),
  ('Olasılık oranı (odds ratio) hangi durumda göreli riske yaklaşık olarak eşit kabul edilebilir?', 'Sonuç nadir görüldüğünde', ['Sonuç çok yaygın olduğunda', 'Örneklem çok küçük olduğunda', 'Maruziyet hiç görülmediğinde'], 'Olay nadir olduğunda olasılık (odds) ile risk değerleri birbirine çok yakındır. Yaygın sonuçlarda olasılık oranı göreli riski abartır.'),
  ('Bir hastalığın toplumdaki sıklığı %1\'dir. Bir test hastaların %90\'ını doğru biçimde pozitif, sağlıklıların %9\'unu yanlışlıkla pozitif buluyor. Testi pozitif çıkan birinin gerçekten hasta olma olasılığı yaklaşık ne kadardır?', '%9', ['%90', '%91', '%50'], '10.000 kişide 100 hasta vardır; 90\'ı pozitif çıkar. 9.900 sağlıklıdan yaklaşık 891\'i de pozitif çıkar. Pozitiflerin 90/981 ≈ %9\'u gerçekten hastadır.'),
  ('Bir şehirde taksilerin %85\'i yeşil, %15\'i mavidir. Gece yaşanan bir kazaya karışan taksiyi tanık "mavi" olarak tanımlıyor; tanığın renkleri doğru ayırt etme oranı %80\'dir. Taksinin gerçekten mavi olma olasılığı yaklaşık kaçtır?', '%41', ['%80', '%15', '%65'], 'Mavi ve doğru tanınan: 0,15 × 0,8 = 0,12. Yeşil ve yanlışlıkla mavi denen: 0,85 × 0,2 = 0,17. Olasılık 0,12 / 0,29 ≈ %41\'dir. Kahneman ve Tversky\'nin bu sorusunda çoğu kişi %80 der.'),
  ('Aynı tarama testi, hastalığın %1 görüldüğü genel nüfusta ve %30 görüldüğü belirtili hastalarda kullanılıyor. Pozitif sonucun güvenilirliği nasıl değişir?', 'Belirtili hastalarda pozitif sonuç daha güvenilirdir.', ['Her iki grupta da tamamen aynıdır.', 'Genel nüfusta pozitif sonuç daha güvenilirdir.', 'Yaygınlık arttıkça yanlış pozitif oranı da aynı ölçüde artar.'], 'Test öncesi olasılık yükseldikçe pozitif sonucun gerçek hastalığı gösterme olasılığı da yükselir. Bu yüzden testler genellikle belirtisi olanlarda daha anlamlıdır.'),
  ('İki farklı birimdeki değişkeni (örneğin sıcaklık ve satış) iki ayrı dikey eksenle aynı grafik üzerinde gösteren bir sunum için hangi uyarı yerindedir?', 'Eksen ölçekleri seçilerek eğriler istendiği kadar ilişkili gösterilebilir.', ['Çift eksenli grafikler her zaman nedenselliği kanıtlar.', 'Çift eksenli grafikler yalnızca bir değişkeni gösterebilir.', 'Çift eksen kullanılması korelasyonu hesaplamayı her durumda imkânsız kılar.'], 'Her eksenin aralığı ayrı ayarlanabildiği için eğrilerin örtüşmesi tasarım tercihine bağlıdır. Görsel örtüşme ilişki kanıtı değildir.'),
  ('Bir hisse senedi bir yıl %20 değer kaybediyor. Önceki değerine dönmesi için ertesi yıl yüzde kaç değer kazanması gerekir?', '%25', ['%20', '%40', '%15'], '100 TL\'lik hisse 80 TL\'ye düşer. 80 TL\'den 100 TL\'ye çıkmak 20 / 80 = %25 artış gerektirir.'),
  ('ABD\'de böbrek kanseri oranının en düşük olduğu ilçelerin çoğunun kırsal ve az nüfuslu olduğu bulunmuş; ancak en yüksek oranlı ilçelerin çoğu da kırsal ve az nüfusludur. Bu örüntünün açıklaması nedir?', 'Küçük nüfuslarda oranlar şans eseri uçlara savrulur.', ['Kırsal yaşamın aynı anda hem koruyucu hem zararlı olduğu ve bunun kanıtlandığı', 'Şehirlerde kanser kayıtlarının hiç tutulmaması', 'Kırsal ilçelerde hiç doktor bulunmaması'], 'Az nüfuslu bölgelerde birkaç vaka bile oranı çok yükseltir ya da düşürür. Uç değerlerin küçük birimlerde toplanması nedensel değil istatistikseldir.'),
  ('Küçük örneklemli bir çalışmada büyük bir etki bulunup daha büyük örneklemli tekrarlarda etkinin giderek küçüldüğünün görülmesine verilen ad hangisidir?', 'Düşüş etkisi', ['Hawthorne etkisi ve buna eşlik eden gözlenme bilinci', 'Tavan etkisi', 'Pygmalion etkisi'], 'İlk çalışmalar, şans eseri büyük çıkan etkilerin yayımlanma olasılığı yüksek olduğu için etkiyi abartabilir. Sonraki tekrarlarda etki ortalamaya doğru küçülür.'),
  ('Bir çalışmanın aynı veri ve aynı kodla yeniden analiz edilip aynı sonuçların elde edilmesi (yeniden üretilebilirlik) ile yeni veriyle tekrar edilmesi (replikasyon) arasındaki fark neden önemlidir?', 'İlki hesaplama hatalarını, ikincisi bulgunun genel geçerliliğini sınar.', ['İkisi tamamen aynı şeydir ve aynı sorunları ortaya koyar.', 'İlki yeni katılımcı gerektirir, ikincisi gerektirmez ve daha kolaydır.', 'Yalnızca ilki bilimsel yöntemin bir parçasıdır.'], 'Aynı veriyle aynı sonuca ulaşmak analizin doğruluğunu, yeni veriyle aynı sonuca ulaşmak ise etkinin gerçek ve genellenebilir olduğunu gösterir.'),
  ('Bir meta-analizde çalışmaların sonuçları birbirinden çok farklı çıkmıştır; bazıları güçlü yarar, bazıları zarar göstermektedir. Bu duruma ne ad verilir ve ne yapılmalıdır?', 'Heterojenlik; farkın kaynakları araştırılmalıdır.', ['Homojenlik; sonuçlar tek bir ortalamada birleştirilip farklar göz ardı edilmelidir.', 'Yayın yanlılığı; çalışmalar silinmelidir.', 'Tip I hata; analiz iptal edilmelidir.'], 'Çalışmalar arası büyük farklılık, örneklem, doz ya da yöntem farklarından kaynaklanabilir. Bu durumda tek bir ortalama etki yanıltıcı olabilir; alt grup ya da meta-regresyon analizleri yapılır.'),
  ('Sigaranın kalp hastalığına etkisini incelerken araştırmacı kan basıncını analizde "kontrol" ediyor; oysa sigara kan basıncını yükselterek de kalbe zarar veriyor. Bu düzeltmenin sonucu ne olur?', 'Sigaranın toplam etkisi olduğundan küçük görünür.', ['Sigaranın toplam etkisi olduğundan çok daha büyük ve abartılı görünür.', 'Düzeltmenin hiçbir etkisi olmaz.', 'Sigaranın etkisi tersine döner ve koruyucu görünür.'], 'Aracı bir değişkeni kontrol etmek, etkinin o yol üzerinden geçen kısmını analizden çıkarır. Bu nedenle toplam etki kestiriliyorsa aracılar düzeltilmemelidir.'),
  ('Karıştırıcı değişken ile aracı değişkeni ayıran temel özellik nedir?', 'Aracı nedenin sonucudur; karıştırıcı nedenden önce gelir ve onu etkiler.', ['Karıştırıcı her zaman ölçülebilir, aracı ise hiçbir koşulda ölçülemez ve gözlenemez.', 'İkisi aynı kavramın farklı adlarıdır.', 'Aracı yalnızca deneylerde, karıştırıcı yalnızca anketlerde görülür.'], 'Karıştırıcı hem nedeni hem sonucu etkileyen ortak bir etkendir. Aracı ise neden tarafından etkilenir ve etkiyi sonuca taşır.'),
  ('Tavan etkisi bulunan iki grubun puanları arasında korelasyon hesaplandığında genellikle ne beklenir?', 'Gerçek ilişkiden daha zayıf bir korelasyon', ['Gerçek ilişkiden daha güçlü ve kusursuza yakın, abartılı bir korelasyon', 'Tam olarak 1\'e eşit bir korelasyon', 'Her zaman negatif bir korelasyon'], 'Puanlar üst sınırda toplandığında değişkenlik azalır. Sınırlı değişkenlik (aralık kısıtlaması) korelasyonu zayıflatır.'),
  ('İki değişkenin yalnızca dar bir aralıkta incelenmesi, örneğin yalnızca en başarılı öğrencilerin seçildiği bir üniversitede giriş puanı ile not ortalaması ilişkisine bakılması, korelasyonu nasıl etkiler?', 'Korelasyonu olduğundan zayıf gösterir.', ['Korelasyonu olduğundan güçlü gösterir.', 'Korelasyonun işaretini kesin olarak tersine çevirir.', 'Korelasyonu hiç etkilemez.'], 'Aralık kısıtlaması değişkenliği azaltır ve gözlenen korelasyonu düşürür. Bu yüzden seçici okullarda giriş sınavı başarıyı zayıf yordar gibi görünebilir.'),
  ('İki değişken arasındaki korelasyon katsayısı r = 0,9 olan bir veri setinde x\'in 1 birim artmasıyla y\'nin ne kadar değiştiği sorusu neden r\'den doğrudan okunamaz?', 'r ilişkinin gücünü gösterir, eğimi değil.', ['r her zaman eğimin tam iki katına eşittir.', 'r yalnızca negatif ilişkilerde eğimi verir.', 'r\'nin birimi değişkenlerin birimiyle aynıdır.'], 'Korelasyon birimsizdir ve noktaların doğruya ne kadar yakın olduğunu gösterir. Eğim ise değişkenlerin ölçeğine bağlıdır ve regresyonla bulunur.'),
  ('Sınıf ortalamaları kullanılarak hesaplanan korelasyon, aynı verideki öğrenci düzeyinde hesaplanan korelasyondan genellikle nasıl farklıdır?', 'Daha güçlü çıkar.', ['Daha zayıf çıkar.', 'Her zaman aynıdır.', 'Her zaman sıfırdır.'], 'Ortalamalar bireysel dalgalanmaları törpüler, bu yüzden grup düzeyinde korelasyon çoğu zaman şişkin çıkar. Bu durum ekolojik yanılgıya zemin hazırlar.'),
  ('Bir kişinin belli bir tedaviyi alması ile almaması durumundaki sonuçlarının karşılaştırılmasına dayanan nedensellik tanımında, gözlenmeyen sonuca ne ad verilir?', 'Karşı-olgusal sonuç', ['Ara sonuç', 'Ortalama (beklenen) sonuç', 'Ham sonuç'], 'Nedensel etki, aynı kişinin hem tedavili hem tedavisiz sonucunun farkıdır. Bunlardan yalnızca biri gözlenebildiği için diğeri karşı-olgusaldır; rastgele gruplar bu eksikliği ortalama düzeyde giderir.'),
  ('Hem yetenek hem de çok çalışma bir konservatuvara kabul edilme şansını artırıyorsa, yalnızca kabul edilen öğrencilere bakıldığında yetenek ile çalışma arasında nasıl bir ilişki görülebilir?', 'Yapay bir negatif ilişki', ['Gerçeğe uygun güçlü bir pozitif ilişki', 'Hiçbir koşulda ilişki gözlenmez', 'Her durumda kusursuz bir pozitif ilişki'], 'Ortak bir sonuca (kabul) göre seçim yapmak, bu sonucun iki nedeni arasında sahte bir ilişki yaratır. Yetenekli olup az çalışanlar ve tersi kabul edilir; buna çarpıştırıcı yanlılığı denir.'),
  ('Akciğer kanserinin sigara dışında radon gazı, asbest ve hava kirliliğiyle de ilişkili olması, Bradford Hill\'in hangi ölçütünün katı biçimde uygulanamayacağını gösterir?', 'Özgüllük', ['Zamansallık', 'Tutarlılık', 'Doz-yanıt'], 'Özgüllük ölçütü bir nedenin tek bir sonuca, bir sonucun tek bir nedene bağlı olmasını arar. Pek çok hastalığın birden çok nedeni olduğundan bu ölçüt zayıftır.'),
  ('Kanser tarama programına katılan hastaların tanıdan sonraki yaşam süresinin daha uzun çıkması, taramanın ömrü uzattığını neden kanıtlamayabilir?', 'Erken tanı, ölüm tarihi değişmese de süreyi uzatır.', ['Taramaya katılanlar daha geç tanı aldığı için yaşam süresi yapay olarak kısalır.', 'Tarama tanı süresini hiç değiştirmez.', 'Yaşam süresi tanıdan önce hesaplanır.'], 'Bu durum öne çekilmiş tanı (lead-time) yanlılığıdır. Hastalık daha erken saptandığı için "tanıdan sonraki süre" uzar ama kişi aynı tarihte ölebilir.'),
  ('Tarama programlarında yavaş ilerleyen tümörlerin, hızlı ilerleyenlere göre taramayla daha sık yakalanması hangi yanlılığa yol açar?', 'Süre (length-time) yanlılığı', ['Hatırlama yanlılığı', 'Hawthorne etkisi', 'Pygmalion etkisi'], 'Yavaş büyüyen tümörler belirti vermeden uzun süre saptanabilir kalır. Taramayla bulunanlar bu nedenle zaten daha iyi seyirli olanlardır ve tarama olduğundan etkili görünür.'),
  ('Gözlemsel bir çalışmada ilaç kullananların "ilacı almaya başladıkları tarih" yerine çalışmanın başından itibaren izlenmesi, ilacı başlamadan ölenlerin kullanmayan grupta sayılmasına yol açıyor. Bu hata ilacı nasıl gösterir?', 'Olduğundan daha koruyucu', ['Olduğundan daha zararlı', 'Tam olarak etkisiz', 'Etkisi hesaplanamaz ve yorumlanamaz'], 'İlaç kullanan gruptaki kişiler ilaca başlayana kadar hayatta kalmak zorundadır. Bu "ölümsüz zaman" yanlılığı ilaç grubuna sahte bir sağkalım avantajı verir.'),
  ('Bir çalışmada maruziyetin ölçümündeki hata, hasta ve sağlıklı gruplarda aynı oranda yapılmıştır. Bu tür yanlış sınıflandırmanın etkisi genellikle nedir?', 'İlişkiyi sıfıra doğru zayıflatır.', ['İlişkiyi her zaman abartır.', 'İlişkinin yönünü kesin olarak tersine çevirir.', 'İlişkiyi hiç etkilemez.'], 'Farklılaşmayan (iki grupta eşit) yanlış sınıflandırma, grupları birbirine benzetir ve gerçek ilişkiyi küçültür. Farklılaşan yanlış sınıflandırma ise her iki yönde de yanlılık yaratabilir.'),
  ('Bir hastalığın tanı ölçütleri değiştirildiğinde, hafif vakaların yeni bir evreye geçirilmesiyle her iki evrenin de ortalama sağkalımının iyileştiği görülür. Bu olgu hangi adla bilinir?', 'Will Rogers olgusu', ['Hawthorne olgusu', 'Berkson olgusu', 'Simpson olgusu'], 'Kötü gruptaki en iyi vakalar üst gruba taşınınca iki grubun ortalaması da düzelir, ama hiçbir hastanın durumu değişmez. Adı bir Amerikalı mizahçının esprisinden gelir.'),
  ('"Bu kan örneği sanığa ait değilse böyle bir eşleşme olasılığı milyonda birdir; öyleyse sanığın masum olma olasılığı milyonda birdir" akıl yürütmesindeki hata nedir?', 'İki farklı koşullu olasılığın birbirine karıştırılması', ['Olasılığın yanlış biçimde yüzde ile değil kesirle ifade edilmesi', 'Kan örneğinin hiç alınmamış olması', 'Milyonda birin çok büyük bir olasılık olması'], 'P(eşleşme | masum) ile P(masum | eşleşme) aynı şey değildir. Bu "savcı yanılgısı" olarak bilinir; büyük bir nüfusta başka eşleşen kişiler de olabilir.'),
  ('Cook ve Campbell\'ın geçerlilik sınıflamasında, iki değişken arasında bir ilişki olup olmadığına ilişkin çıkarımların istatistiksel olarak sağlam olmasına ne denir?', 'İstatistiksel sonuç geçerliliği', ['Görünüş geçerliliği ve kapsam geçerliliği', 'Ekolojik geçerlilik', 'Kapsam geçerliliği'], 'Düşük güç, varsayımları ihlal edilmiş testler ya da çoklu karşılaştırmalar bu geçerlilik türünü tehdit eder. Diğer üç tür iç, yapı ve dış geçerliliktir.'),
  ('Standart sapma ile ortalamanın standart hatası arasındaki fark en doğru biçimde hangisinde verilmiştir?', 'SS bireylerin, standart hata ortalamanın dalgalanmasını gösterir.', ['İkisi tamamen aynı şeyi ölçer.', 'Standart hata bireylerin, standart sapma ortalamanın dalgalanmasını gösterir.', 'Standart hata örneklem büyüdükçe artar.'], 'Standart sapma verilerin yayılımıdır. Standart hata ise örneklem ortalamasının belirsizliğidir ve örneklem büyüklüğünün kareköküne bölünerek küçülür.'),
  ('Eksik verilerin, eksik olma olasılığının hiçbir değişkenle ilişkili olmadığı türüne ne ad verilir?', 'Tamamen rastgele eksik veri', ['Rastgele olmayan eksik veri', 'Sistematik eksik veri', 'Seçici eksik veri'], 'Tamamen rastgele eksik (MCAR) veride, örneğin bir anket kâğıdının rastgele kaybolmasında, eksik gözlemleri çıkarmak yanlılık yaratmaz; yalnızca gücü azaltır.'),
  ('Yazı-tura dizilerinde insanlardan rastgele bir dizi yazmaları istendiğinde, gerçek rastgele dizilere göre genellikle ne yaparlar?', 'Uzun serilerden kaçınıp çok sık değişim yazarlar.', ['Gerçek dizilerden çok daha uzun seriler yazarlar.', 'Hep aynı yüzü yazarlar.', 'Gerçek rastgele dizilerle tam olarak aynı sıklıkta seri yazarlar.'], 'Gerçek rastgele dizilerde beklenenden uzun seriler oldukça sık görülür. İnsanlar ise rastgeleliği "düzenli karışım" sanır; bu yüzden gerçek kümelenmeleri anlamlı bulur.'),
  ('Bir olayın olasılığı 0,2 ise olasılık oranı (odds) kaçtır?', '0,25', ['0,2', '0,8', '4'], 'Odds = p / (1 − p) = 0,2 / 0,8 = 0,25\'tir. Olasılık ile odds küçük değerlerde birbirine yakındır, büyük değerlerde belirgin biçimde ayrışır.'),
  ('Bir ilaç denemesinde yalnızca katılımcıların hangi tedaviyi aldığını bilmediği, araştırmacıların ise bildiği düzenleme hangi yanlılığı önlemekte yetersiz kalır?', 'Değerlendirici yanlılığını', ['Plasebo etkisini', 'Katılımcıların beklenti etkisini', 'Katılımcıların gruba göre farklı davranmasını'], 'Tek kör düzende katılımcı beklentisi kontrol edilir, ancak sonucu değerlendiren kişinin beklentisi ölçümlere sızabilir. Bu nedenle çift kör düzen tercih edilir.'),
  ('Bir vaka-kontrol çalışmasında hastalar ile sağlıklılar seçilip geçmiş maruziyetleri karşılaştırılmıştır. Bu tasarımda göreli risk yerine hangi ölçü hesaplanır?', 'Olasılık oranı', ['İnsidans hızı', 'Mutlak risk', 'Tedavi edilmesi gereken sayı'], 'Vaka-kontrol çalışmalarında hastaların oranını araştırmacı belirlediği için risk doğrudan hesaplanamaz. Bu nedenle maruziyet olasılıklarının oranı (odds ratio) kullanılır.'),
  ('1990\'larda gözlemsel çalışmalar menopoz sonrası hormon tedavisi alan kadınlarda kalp hastalığının daha az görüldüğünü göstermişti; 2002\'de yayımlanan büyük rastgele kontrollü Women\'s Health Initiative deneyi ise riskin azalmadığını, hatta bazı risklerin arttığını buldu. Bu çelişkinin en çok kabul gören açıklaması nedir?', 'Hormon kullananların zaten daha sağlıklı ve varlıklı olması', ['Rastgele deneyde hormonun hiç verilmemiş olması', 'Gözlemsel çalışmaların çok daha büyük örneklemle yapılıp kesin sonuç vermesi', 'Kalp hastalığının 2002\'den sonra tanımının değişmesi'], 'Gözlemsel çalışmalarda hormon tedavisi alan kadınlar sosyoekonomik düzey ve sağlık davranışları bakımından farklıydı ("sağlıklı kullanıcı etkisi"). Rastgele atama bu karıştırıcıları dengeleyince yarar kayboldu.'),
  ('Çocukların ödülü erteleyebilme süresinin ileriki başarıyı yordadığını öne süren "lokum testi" bulgusu, 2018\'de daha büyük ve çeşitli bir örneklemle yeniden incelendiğinde ilişkinin büyük ölçüde zayıfladığı görülmüştür. Bu zayıflamanın başlıca nedeni neydi?', 'Aile geliri gibi etkenler katılınca etkinin küçülmesi', ['Çocukların lokumu sevmemesi', 'Testin artık uygulanamaz olması', 'İlk çalışmanın çocukları hiç izlemeyip yalnızca ailelere soru sorması'], 'Watts, Duncan ve Quan\'ın çalışması, sosyoekonomik ve ailesel etkenler denetlendiğinde erteleme süresi ile sonraki başarı arasındaki ilişkinin büyük ölçüde azaldığını gösterdi.'),
  ('Büyük, çok laboratuvarlı tekrar projelerinde başarısız olduğu bildirilen bulgulardan biri hangisidir?', 'İrade gücünün tükenen bir kaynak olduğu fikri', ['Sigaranın akciğer kanseri riskini artırması', 'Plasebo kontrollü deneylerin beklenti yanlılığını azaltması', 'Rastgele atamanın grupları dengelemesi'], '2016\'da 23 laboratuvarda yürütülen kayıtlı tekrar projesi, ego tükenmesi etkisini sıfıra yakın buldu. Diğer seçenekler sağlam biçimde tekrarlanmış bulgulardır.'),
  ('Aşağıdakilerden hangisi korelasyon nedensellik değildir ilkesinin aşırı ve yanlış bir uygulamasıdır?', 'Güçlü kanıtlara rağmen her korelasyonu anlamsız saymak', ['Gözlemsel bir ilişkide olası karıştırıcıları tek tek araştırmak', 'Nedensellik için ek kanıt istemek', 'Ters nedensellik olasılığını değerlendirmek'], 'Korelasyon tek başına nedenselliği kanıtlamaz, ama nedensellik çoğu zaman korelasyonla kendini gösterir. Doz-yanıt, tutarlılık ve mekanizma gibi kanıtlarla birlikte gözlemsel veriler güçlü sonuçlara ulaşabilir.'),
  ('Bir çalışma, gece ışığı açık uyuyan bebeklerin ileride daha sık miyop olduğunu bulmuştur. Sonraki araştırmalar miyop ebeveynlerin gece ışığını daha çok açık bıraktığını göstermiştir. Bu durum ilk bulgunun yorumunu nasıl değiştirir?', 'Ebeveyn miyopisi, ilişkiyi açıklayan bir karıştırıcıdır.', ['Gece ışığının miyopiye yol açtığı kesinleşmiştir.', 'Bebeklerin miyopisi ebeveynlerin ışık tercihine neden olmuştur.', 'İlk bulgu tamamen doğru kalmıştır ve değişmemiştir.'], 'Miyopi kalıtsal olabildiği için miyop ebeveynlerin çocukları da miyop olma eğilimindedir. Bu ebeveynler aynı zamanda ışığı daha çok açık bıraktığından ilişki sahte olabilir. 1999\'daki bu bulgu 2000\'de böyle sorgulandı.'),
  ('Gözlemsel bir çalışmada bilinen karıştırıcılar düzeltildikten sonra kalan ilişkinin, ölçülmemiş bir karıştırıcı tarafından açıklanabilmesi için ne kadar güçlü olması gerektiğini gösteren ölçü hangisidir?', 'E-değeri', ['p-değeri', 'Cronbach alfa', 'Cohen kappa'], 'E-değeri, gözlenen ilişkiyi tamamen açıklamak için ölçülmemiş bir karıştırıcının hem maruziyetle hem sonuçla en az ne kadar güçlü ilişkili olması gerektiğini gösterir. Büyük E-değeri sonuca güveni artırır.'),
  ('Bir veri setinde cep telefonu kullanımı ile beyin tümörü arasında ilişki aranıyor. Tümörlü hastalar telefonlarını tümör tarafındaki kulağa daha çok tuttuklarını bildiriyor. Bu bildirim hangi yanlılığa özellikle açıktır?', 'Hatırlama yanlılığı', ['Hayatta kalan yanlılığı', 'Tavan etkisi', 'Yenilik etkisi'], 'Tümör tanısı alan kişiler olası nedenleri sorgular ve geçmiş kullanımlarını tümör tarafına yönelik olarak abartabilir. Nesnel kullanım kayıtları bu yanlılığı azaltır.'),
  ('Bir A/B testinde araştırmacı, sonuçlara her saat bakıp B önde olduğu anda testi durduruyor. Bu uygulama sonucu nasıl etkiler?', 'Yanlış pozitif bulma olasılığını artırır.', ['Testin gücünü kesin olarak artırır ve hatayı sıfırlar.', 'Rastgele atamanın yararını iki katına çıkarır.', 'Sonuç üzerinde hiçbir etkisi yoktur.'], 'Sürekli bakıp uygun anda durmak, şans dalgalanmalarını yakalama olasılığını yükseltir. Örneklem büyüklüğü önceden belirlenmeli ya da ardışık analiz yöntemleri kullanılmalıdır.'),
  ('İki gözlemci 100 davranış kaydının 90\'ında aynı kodu vermiştir. Ancak davranışların çoğu tek bir kategoriye düştüğü için şans eseri uyuşma da yüksektir. Bu durumda uyum için yalnızca yüzde uyuşmayı raporlamanın sakıncası nedir?', 'Şansla beklenen uyuşmayı ayırmadığı için uyumu abartabilir.', ['Yüzde uyuşma her zaman uyumu olduğundan düşük ve kötümser gösterir.', 'Yüzde uyuşma yalnızca iki kategoride hesaplanabilir.', 'Yüzde uyuşma puanlayıcı sayısını gösterir.'], 'Cohen\'in kappa katsayısı, gözlenen uyuşmadan şansla beklenen uyuşmayı çıkararak düzeltilmiş bir uyum ölçüsü verir.'),
  ('Bir kan şekeri ölçüm cihazı, şeker düzeyi yükseldikçe gerçek değerin giderek daha fazla altında ölçüm yapıyor. Bu hata hangi türdendir?', 'Düzeye bağlı sistematik hata', ['Sabit büyüklükte rastlantısal hata', 'Örnekleme hatası', 'Hatırlama hatası'], 'Hata yönlüdür ve ölçülen değerle birlikte büyür; dolayısıyla sistematiktir. Bu tür hatalar özellikle yüksek değerlerde klinik kararları yanıltabilir.'),
  ('Bir puanlayıcının sınav kâğıtlarını okurken her kâğıda bir önceki kâğıdın niteliğine göre görece puan vermesi, örneğin çok iyi bir kâğıttan sonra ortalama bir kâğıdı düşük puanlaması hangi etkiye örnektir?', 'Karşıtlık (sıra) etkisi', ['Hawthorne (gözlenme) etkisi', 'Pygmalion etkisi', 'Tavan etkisi'], 'Değerlendirmeler mutlak ölçüte değil yakın örneklere göre yapıldığında okuma sırası puanları etkiler. Ölçütlere dayalı puanlama ve kâğıtların karıştırılması bu etkiyi azaltır.'),
  ('Uluslararası karşılaştırmalı bir ankette "mutluluk" sorusunun farklı dillere çevirisinde anlam farklılıkları olduğu fark ediliyor. Ülkeler arası farkları yorumlarken hangi sorun ortaya çıkar?', 'Ölçüm eşdeğerliğinin sağlanamaması', ['Örneklem büyüklüğünün artması', 'Ankete yanıt süresinin kısalması', 'Mutluluğun her ülkede eşit düzeyde ve aynı biçimde yaşanması'], 'Aynı soru farklı dillerde farklı kavramları çağrıştırıyorsa, gözlenen farklar gerçek mutluluk farkı değil çeviri farkı olabilir. Ölçüm değişmezliği sınanmalıdır.'),
  ('İç geçerliliği tehdit eden "seçim–olgunlaşma etkileşimi" nedir?', 'Grupların zamanla farklı hızlarda değişmesi', ['Ölçme aracının çalışma ortasında değişmesi', 'Katılımcıların gözlendiğini bilmesi', 'Ön testin son testi etkilemesi'], 'Gruplar baştan farklıysa (örneğin farklı yaşlarda), doğal gelişim hızları da farklı olabilir. Bu durumda gruplar arası fark müdahaleden değil, farklı olgunlaşmadan kaynaklanabilir.'),
  ('Bir salgın sırasında vaka sayıları logaritmik ölçekli bir dikey eksende gösterildiğinde eğrinin düz bir çizgi gibi yükselmesi neyi gösterir?', 'Sabit oranlı (üstel) büyümeyi', ['Her gün aynı sayıda yeni vaka eklendiğini', 'Vakaların azaldığını', 'Salgının durduğunu'], 'Logaritmik ölçekte eşit aralıklar eşit çarpanları temsil eder. Bu nedenle düz bir çizgi, vakaların her dönemde aynı oranda katlandığını gösterir.'),
  ('Logaritmik ölçekli bir grafik gösteriminde eğrinin eğiminin azalması, okuyucular tarafından sıkça nasıl yanlış yorumlanır?', 'Vakaların azaldığı sanılır; oysa yalnızca artış yavaşlamıştır.', ['Vakaların arttığı sanılır, oysa kesin olarak azalmıştır.', 'Eğrinin eğimi hiçbir bilgi taşımaz.', 'Logaritmik ölçek yalnızca negatif sayılar için kullanıldığından okunamaz.'], 'Eğim azalırken vaka sayısı hâlâ artıyor olabilir. Logaritmik ölçek büyüme hızını gösterir; doğrusal eksen alışkanlığıyla okunduğunda yanıltıcı olabilir.'),
  ('Bir şirket, "Ürünümüz rakibinden %200 daha etkili" diyor; ölçümde rakip ürün 1 birim, kendi ürünleri 3 birim etki göstermiştir. Bu ifade için doğru değerlendirme hangisidir?', 'Doğrudur; %200 fazla, rakibin 3 katı demektir.', ['İfade yanlıştır; artış %300\'dür.', 'İfade yanlıştır; artış %20\'dir.', 'İfade yanlıştır; ürün rakibin 2 katı etkilidir.'], '3 birim, 1 birimden 2 birim, yani %200 fazladır; bu da 3 kat demektir. "% fazla" ile "kat" ifadeleri sıkça karıştırılır.'),
  ('Çok sayıda testin yapıldığı genetik çalışmalarda, anlamlı sonuçlar arasında yanlış pozitiflerin beklenen oranını denetlemeye yönelik yaklaşım hangisidir?', 'Yanlış keşif oranının (FDR) denetlenmesi', ['Anlamlılık düzeyinin 0,5\'e çıkarılması', 'Testlerin yarısının rastgele silinmesi', 'Yalnızca ilk testin raporlanması'], 'Benjamini–Hochberg yöntemi gibi FDR yaklaşımları, Bonferroni\'ye göre daha az tutucudur ve anlamlı bulunanlar arasındaki yanlış pozitiflerin oranını sınırlar.'),
  ('Bir ankette "%52 ± 3" sonucu verilmiştir. Bu "± 3" ifadesi neyi göstermez?', 'Yanıt vermeme ya da soru ifadesinden doğan yanlılığı', ['Rastgele örneklemeden kaynaklanan belirsizliğin büyüklüğünü', 'Kestirimin olası aralığını', 'Yaklaşık %49 ile %55 arasını'], 'Hata payı yalnızca rastgele örnekleme belirsizliğini kapsar. Yanıt vermeme, soru biçimi ya da örneklem çerçevesindeki sistematik hatalar bu paya dahil değildir.'),
  ('Bayesçi bir bakış açısıyla, yeni bir kanıtın bir hipoteze olan inancı ne kadar değiştireceği hangi iki şeye bağlıdır?', 'Önsel olasılığa ve kanıtın ayırt ediciliğine', ['Yalnızca kanıtın kaynağının ünlü ya da saygın olup olmamasına', 'Yalnızca araştırmacının kişisel isteğine', 'Yalnızca örneklemin coğrafi konumuna'], 'Bayes kuramında sonsal inanç, önsel olasılık ile olabilirlik oranının birleşimidir. Çok olası olmayan bir iddia için daha güçlü kanıt gerekir.'),
  ('Vitamin takviyesi kullananların daha sağlıklı olduğunu gösteren gözlemsel çalışmalara karşın, bazı büyük rastgele deneylerde (örneğin sigara içenlerde beta-karoten denemelerinde) takviyenin yarar sağlamadığı, hatta riski artırdığı görülmüştür. Bu durum hangi ilkeyi destekler?', 'Gözlemsel ilişkiler, deneyle doğrulanmadan tedavi önerisi olmamalı.', ['Rastgele deneyler her zaman yanlış sonuç verir.', 'Gözlemsel çalışmalar her zaman rastgele deneylerden üstündür.', 'Vitaminlerin hiçbir etkisi olamaz.'], '1990\'larda Finlandiya\'daki ATBC ve ABD\'deki CARET denemelerinde beta-karoten alan sigara içicilerde akciğer kanseri sıklığı arttı. Gözlemsel bulgular karıştırıcılarla şekillenmiş olabilir.'),
  ('Yanıltıcı bir korelasyonu sınamak için dört gözlü bir karşılaştırma yapılıyor. İnsanların saymayı en çok ihmal ettiği, ama değerlendirme için gerekli olan hücre hangisidir?', 'Ne olayın ne nedenin görüldüğü durumlar', ['Hem nedenin hem olayın görüldüğü durumlar', 'Yalnızca olayın görüldüğü durumlar', 'Yalnızca nedenin görüldüğü durumlar'], 'İnsanlar çoğunlukla "dolunay ve yoğun gece" gibi eşleşmelere odaklanır. Sakin geçen sıradan geceler ilişkiyi değerlendirmek için en az onlar kadar gereklidir ama genellikle göz ardı edilir.'),
  ('Bir savaşta yalnızca sayılabilen "öldürülen düşman sayısı"nın başarı göstergesi yapılması ve ölçülemeyen etkenlerin önemsiz sayılması hangi yanılgıya örnektir?', 'McNamara yanılgısı', ['Kumarbaz yanılgısı', 'Hayatta kalan yanlılığı', 'Post hoc yanılgısı'], 'Adını ABD Savunma Bakanı Robert McNamara\'dan alan bu yanılgıda yalnızca ölçülebilen önemli sayılır. Ölçülemeyenin önemsiz ya da var olmadığı varsayımı yanlış kararlara yol açar.'),
  ('1989\'da yayımlanan CAST çalışmasında, kalp krizi sonrası düzensiz atımları baskılayan bazı ilaçların ölüm oranını artırdığı görülmüştür. Bu çalışmadan çıkarılan temel ders nedir?', 'Vekil göstergenin iyileşmesi gerçek sonucun iyileşmesini garanti etmez.', ['Düzensiz kalp atımları zararsızdır.', 'İlaçlar hiçbir zaman ölüm oranını etkilemez.', 'Rastgele deneylerin sonuçları her zaman yanlıştır.'], 'İlaçlar EKG\'deki düzensizlikleri azaltmasına rağmen ölümleri artırdı. Vekil sonlanımlar asıl hasta sonuçlarıyla doğrulanmalıdır.'),
  ('Bir yatırım uzmanının üst üste beş yıl piyasayı geçmesi, onun gerçekten yetenekli olduğunu kanıtlar mı? Binlerce uzmanın bulunduğu bir piyasada en uygun değerlendirme hangisidir?', 'Kanıtlamaz; çok sayıda uzmandan bazıları şansla da başarır.', ['Kesinlikle kanıtlar; beş yıl şansla açıklanamaz.', 'Kanıtlamaz; çünkü piyasalar hiçbir zaman geçilemez.', 'Kesinlikle kanıtlar; uzmanların tamamı aynı başarıyı gösterir.'], 'Her yıl yarı yarıya başarı olasılığıyla 10.000 uzmandan yaklaşık 300\'ü (10.000 / 32) beş yıl üst üste yalnızca şansla başarılı olur. Bu, çoklu karşılaştırmanın günlük bir örneğidir.'),
  ('Bir meta-analizde yayın yanlılığının etkisini düzeltmek için huni grafiğindeki eksik çalışmaları istatistiksel olarak tamamlayan yöntem hangisidir?', 'Kırp ve doldur', ['Tedavi niyeti analizi', 'Bonferroni düzeltmesi', 'Hareketli ortalama'], 'Kırp ve doldur yöntemi asimetrik huni grafiğini simetrik hâle getirmek için eksik görünen çalışmaları tahmin eder ve düzeltilmiş bir genel etki hesaplar.'),
  ('Hastalara verilen hapların plasebo olduğu açıkça söylendiği bazı denemelerde (açık etiketli plasebo) bile belirtilerde iyileşme bildirilmiştir. Bu bulgu hangi açıklamayı en çok destekler?', 'Tedavi ritüelinin de öznel belirtileri etkileyebileceğini', ['Plasebo haplarının gizli etken madde içerdiğini', 'Hastaların söylenenleri hiç anlamadığını', 'Plasebonun nesnel ölçümleri kesin olarak değiştirdiğini'], 'Açık etiketli plasebo çalışmaları, özellikle ağrı ve yorgunluk gibi öznel belirtilerde iyileşme bildirmiştir. Bu etkiler beklenti, koşullanma ve ilgi görme gibi etkenlerle açıklanır.'),
  ('Bir otelde yapılan çalışmada temizlik görevlilerine işlerinin iyi bir egzersiz olduğu söylenmiş ve bu gruptaki görevlilerde birkaç hafta sonra kilo ve kan basıncında azalma bildirilmiştir. Bu sonucu yorumlarken hangi uyarı en yerindedir?', 'Beklenti, davranış ve ölçüm farkları ayrılmadan etki kesin sayılmamalı.', ['Sonuç, beklentinin fizyolojiyi doğrudan değiştirdiğini kesin ve tartışmasız biçimde kanıtlar.', 'Temizlik işi hiçbir fiziksel etkinlik içermez.', 'Kilo ölçümü bu tür çalışmalarda yapılamaz.'], 'Crum ve Langer\'in 2007 çalışması ilginç bulgular sunsa da katılımcılar işyeri dışında da davranışlarını değiştirmiş olabilir. Küçük ve tek bir çalışma tekrar gerektirir.'),
  ('Hassas bir soruda katılımcının yanıtını gizlemek için "yazı gelirse doğru yanıt verin, tura gelirse \'evet\' deyin" gibi bir şans düzeneği kullanılmasına ne ad verilir?', 'Rastgele yanıt tekniği', ['Tedavi niyeti analizi', 'Hareketli ortalama yöntemi', 'Kırp ve doldur yöntemi'], 'Araştırmacı tek tek yanıtların anlamını bilmez, ama olasılık hesabıyla gruptaki gerçek oranı kestirebilir. Bu, sosyal beğenirlik yanlılığını azaltır.'),
  ('Rastgele yanıt tekniğinde katılımcılar yazı gelirse dürüst yanıt veriyor, tura gelirse ne olursa olsun "evet" diyor. Grubun %60\'ı "evet" demişse, hassas davranışın gerçek oranı yaklaşık kaçtır?', '%20', ['%60', '%30', '%10'], 'Evet oranı = 0,5 × 1 + 0,5 × p = 0,60 olduğundan 0,5p = 0,10 ve p = 0,20\'dir. Yazı-tura yanıtların yarısını otomatik "evet"e çevirir.'),
  ('Bir araştırmacı "saldırganlık" yapısını tek bir deneyde yalnızca katılımcının rakibine verdiği ses şiddeti düzeyiyle ölçüyor. Cook ve Campbell\'ın sınıflamasında bu durum hangi yapı geçerliliği tehdidine örnektir?', 'Tek işlem yanlılığı', ['Tarih tehdidi', 'Olgunlaşma tehdidi', 'Ortalamaya dönüş tehdidi'], 'Bir yapıyı tek bir işlemle ölçmek, o işleme özgü ilgisiz özellikleri de ölçüme katar. Birden fazla ve farklı türde ölçüm yapı geçerliliğini güçlendirir.'),
  ('Bir ölçeğin güvenirlik katsayısı 0,90 olarak bulunmuştur. Klasik test kuramına göre bu değer nasıl yorumlanır?', 'Gözlenen varyansın yaklaşık %90\'ı gerçek puan farkından gelir.', ['Katılımcıların %90\'ı doğru yanıt vermiştir.', 'Ölçek %90 olasılıkla geçerlidir.', 'Ölçeğin maddelerinin %90\'ı aynı konuyu sorar.'], 'Güvenirlik katsayısı gerçek puan varyansının toplam varyansa oranıdır. Geri kalan yaklaşık %10 hata varyansıdır; bu katsayı geçerlilik hakkında doğrudan bilgi vermez.'),
  ('Bir araştırmacı veriyi gördükten sonra yönlü (tek kuyruklu) teste geçerek p-değerini yarıya indiriyor. Bu uygulama neden sorunludur?', 'Testi sonuca göre seçmek yanlış pozitif riskini artırır.', ['Tek kuyruklu testler hiçbir zaman kullanılamaz.', 'p-değerini yarıya indirmek etki büyüklüğünü iki katına çıkarır.', 'Tek kuyruklu testler yalnızca negatif etkileri sınar.'], 'Tek kuyruklu test, ancak yön önceden kuramsal olarak belirlenmişse uygundur. Veriye bakarak testi değiştirmek bir p-hackleme biçimidir.'),
  ('Hesaplanmış tek bir %95 güven aralığı için "Gerçek değer %95 olasılıkla bu aralıktadır" demenin klasik (frekansçı) istatistik açısından sorunu nedir?', 'Gerçek değer sabittir; %95 yöntemin uzun dönem başarısıdır.', ['Gerçek değer her zaman aralığın dışındadır.', 'Güven aralığı yalnızca yüzde değerler için hesaplanır.', 'Aralık %5 olasılıkla doğrudur.'], 'Frekansçı yorumda gerçek değer ya aralıktadır ya değildir. %95, aynı yöntemle oluşturulan aralıkların uzun dönemde gerçek değeri yakalama oranıdır.'),
  ('Bir sınıfta 23 öğrenci olduğunda en az iki öğrencinin aynı gün doğmuş olma olasılığı yaklaşık kaçtır?', '%50', ['%6', '%23', '%95'], '23 kişide farklı doğum günü olasılığı yaklaşık 0,49\'dur; en az bir eşleşme olasılığı yaklaşık %50,7\'dir. Sezgilerimiz çakışma sayısını küçümser; bu "doğum günü paradoksu"dur.'),
  ('Çevrimiçi bir tanışma uygulamasında yalnızca eşleşilen kişilere bakan biri, fiziksel çekicilik ile kibarlık arasında negatif bir ilişki fark ediyor. Kişi hem çekici hem kibar olanlarla zaten eşleşmiş, ikisinde de düşük olanları ise hiç seçmemişse bu ilişki nasıl yorumlanmalıdır?', 'Seçim sürecinin yarattığı yapay bir ilişki olabilir.', ['Çekici insanların kesinlikle daha kaba olduğunu kanıtlar.', 'Kibarlığın ölçülemediğini gösterir.', 'Uygulamadaki herkesin aynı olduğunu gösterir.'], 'Her iki özelliğin toplamına göre seçim yapıldığında, seçilenler arasında iki özellik ters yönde ilişkili görünür. Bu, Berkson yanlılığının günlük bir örneğidir.'),
  ('Bir ilçede geçen yıl 200 olan hırsızlık sayısı bu yıl 180\'e düşmüş, ilçenin nüfusu ise 100.000\'den 80.000\'e inmiştir. 1.000 kişi başına hırsızlık oranı nasıl değişmiştir?', '2\'den 2,25\'e yükselmiştir.', ['2\'den 1,8\'e düşmüştür.', 'Değişmemiştir.', '2,25\'ten 2\'ye düşmüştür.'], 'Geçen yıl 200/100 = 2, bu yıl 180/80 = 2,25\'tir. Sayı azalsa da nüfus daha çok azaldığı için oran artmıştır.'),
  ('Hafif vakalarda A tedavisinin başarı oranı 9/10, B\'ninki 80/100; ağır vakalarda A\'nınki 30/100, B\'ninki 2/10\'dur. Toplamda hangi tedavinin ham başarı oranı daha yüksektir?', 'B', ['A', 'İkisi eşittir', 'Hesaplanamaz'], 'Toplamda A: 39/110 ≈ %35, B: 82/110 ≈ %75\'tir. Ancak her iki vaka türünde de A daha başarılıdır (%90\'a %80, %30\'a %20). B\'nin hafif vakaları çok daha fazla almış olması tabloyu tersine çevirir.'),
  ('Bir ankette "Bu yılki ekonomik durumunuz geçen yıla göre nasıl?" sorusuna katılımcıların %55\'i "kötüleşti" demiştir. Aynı ay resmî verilerde ortalama reel gelirin arttığı görülmektedir. Bu iki bulgu nasıl uzlaştırılabilir?', 'Ortalama artarken çoğunluğun durumu kötüleşmiş olabilir.', ['İki bulgudan biri mutlaka sahtedir.', 'Anket katılımcıları soruyu anlamamıştır.', 'Ortalama gelir artarken kimsenin durumu kötüleşemez.'], 'Ortalama, gelirin küçük bir kesimde büyük ölçüde artmasıyla yükselebilir; aynı anda çoğunluğun geliri düşebilir. Ayrıca algı, fiyat artışlarından etkilenebilir.'),
  ('Aylık %10 büyüme bir yıl boyunca sürerse yıl sonundaki değer başlangıcın yaklaşık kaç katı olur?', '3,1', ['2,2', '1,2', '12'], '1,1¹² ≈ 3,14\'tür. Bileşik büyüme, aylık oranların toplanmasıyla (12 × %10 = %120) bulunandan daha yüksek bir sonuç verir.'),
  ('Bir hastalığın yaygınlığı (prevalans) zaman içinde artarken insidansı (yeni vaka hızı) sabit kalmıştır. Bu durumun en olası açıklaması hangisidir?', 'Hastaların daha uzun süre yaşaması', ['Hastalığın daha bulaşıcı hâle gelmesi', 'Yeni vakaların hızla artması', 'Hastalığın tamamen ortadan kalkması'], 'Yaygınlık, yeni vakalar ile hastalık süresine bağlıdır. Tedavi ölümü azaltıp iyileşme sağlamıyorsa hastalar daha uzun süre "vaka" olarak kalır ve yaygınlık artar.'),
  ('Bir şehirde kurulan hız kameralarının yalnızca en çok kaza olan noktalara yerleştirildiği biliniyor. Kameralardan sonra bu noktalarda kazaların azalmasını değerlendirirken hangi iki olgu göz önünde tutulmalıdır?', 'Ortalamaya dönüş ve genel kaza eğilimi', ['Tavan etkisi ve puanlayıcılar arası güvenirlik', 'Simpson paradoksu ve Hawthorne etkisi', 'Yayın yanlılığı ve plasebo etkisi'], 'En kötü noktalar kısmen şans eseri en kötü olabilir ve kendiliğinden iyileşebilir. Ayrıca şehir genelindeki kaza eğilimi de hesaba katılmalıdır.'),
];
